                /**
                 * vratParametryBanky
                 *
                 * @param {string} nazevSbu
                 */
                vratParametryBanky(formular, nazevSbu, ixsEsu, ico, sbu) {
                    const that = this;
                    that.beginOperation("Probíhá kontrola parametrů banky");
                    let defClose = $.Deferred();
                    that.jeBankaVybrana == false;
                    // filtry
                    let filters = { nazev_sbu: nazevSbu, ixs_esu: ixsEsu, ico: ico, sbu: sbu };
                    ;
                    let returnObj = {
                        data: null
                    };
                    // deferred objekt pro zřetězení otázek (deferred = odlozeny)
                    let def = $.Deferred().resolve(returnObj).promise();
                    // obsluha jednotlivých fází
                    this.beginOperation("Načítám data");
                    ////that.element.findForms("formZadaniOverene").findFields("typPrikazu").gradio("option", "radios", []);
                    def.then(function (returnObj) {
                        that.isl.Banka.read(filters)
                            .get()
                            .done(function (ret) {
                            that.bankaParametryDavky = ret.data;
                            that.bankaValueGenerovani = ret.data;
                            //that.element.findForms("formZadani").findFields("typPrikazu").show("fast");
                            //konec parametru banky
                            that.dataBankaDto = ret.data;
                            that.vstupniDataDto.banka = ret.data;
                            def = $.Deferred();
                            var radioCount = that.element.findForms("formZadani").findFields("typPrikazu")[0].childNodes.length;
                            for (var i = 0; i < radioCount; i++) {
                                that.element.findForms("formZadani").findFields("typPrikazu")[0].childNodes[0].remove();
                            }
                            if (ret.data.parametryDopresnujici?.vyb_typ_dav != undefined && ret.data.parametryDopresnujici?.vyb_typ_dav != null) {
                                var typDav = ret.data.parametryDopresnujici?.vyb_typ_dav;
                                var radios = new Array();
                                for (var i = 0; i < typDav.length; i++) {
                                    if (typDav[i] == 10) {
                                        that.element.findForms("formZadani").findFields("typPrikazu").gradio("addRadio", { id: "r1", value: 'dom', label: 'Domácí' });
                                        //that.radioButtons?.push(new GObservableObject({ id: "r1", value: 'dom', label: 'Domácí' }));
                                        radios.push({ id: "r1", value: 'dom', label: 'Domácí' });
                                    }
                                    else if (typDav[i] == 20) {
                                        //that.element.findForms("formParametryBanky").findFields("typPrikazu").gradio("enableRadio", "r2", true)
                                        that.element.findForms("formZadani").findFields("typPrikazu").gradio("addRadio", { id: "r2", value: 'domzah', label: 'Domácí+Zahraniční', disabled: false });
                                        that.typPrikazuDomZah = true;
                                        radios.push({ id: "r2", value: 'domzah', label: 'Domácí+Zahraniční' });
                                    }
                                    else if (typDav[i] == 30) {
                                        //that.element.findForms("formParametryBanky").findFields("typPrikazu").gradio("enableRadio", "r3", true)
                                        that.element.findForms("formZadani").findFields("typPrikazu").gradio("addRadio", { id: "r3", value: 'zah', label: 'Zahraniční', disabled: false });
                                        radios.push({ id: "r3", value: 'zah', label: 'Zahraniční' });
                                    }
                                    else if (typDav[i] == 40) {
                                        //that.element.findForms("formParametryBanky").findFields("typPrikazu").gradio("enableRadio", "r4", true)
                                        that.element.findForms("formZadani").findFields("typPrikazu").gradio("addRadio", { id: "r4", value: 'sep', label: 'SEPA', disabled: false });
                                        radios.push({ id: "r4", value: 'sep', label: 'SEPA' });
                                    }
                                }
                                that.radioButtons = radios;
                                //Oznaceni prvni volby v gradio jako True
                                that.element.findForms("formZadani").findFields("typPrikazu").gradio("setValue", "dom");
                                if (that.typPrikazuDomZah == true) {
                                    that.element.findForms("formZadani").findFields("typPrikazu").gradio("setValue", "domzah");
                                    that.typPrikazuDomZah = false;
                                }
                                if (that.radioInitialValue != undefined) {
                                    that.element.findForms("formZadani").findFields("typPrikazu").gradio("setValue", that.radioInitialValue);
                                }
                                //Kontrola, zda vybrana banka obsahuje dodatkove prikazy (zatim pouze CNB)
                                if (ret.data.parametryDopresnujici.vyb_gen_dod_pri) {
                                    that.element.findForms("formZadani").findFields("gen_dod_pri").show("fast");
                                }
                                else {
                                    that.element.findForms("formZadani").findFields("gen_dod_pri").hide("fast");
                                }
                            }
                            //Ulozeni vstupnich parametru z formulare do DTO
                            that.element.findForms("formZadani").findFields().gfield("model", "collect", that.vstupniDataDto);
                            that.endOperation();
                            return ret;
                        })
                            .fail(function (xhr, type, vobj) {
                            //BucWizard.showErrorFlash(vobj.baseMessage, that);
                            // operace nedopadla
                            def.reject(xhr, type, vobj);
                            //that.endOperation();
                        });
                        let def = $.Deferred();
                        that.endOperation();
                        return def.promise();
                    }).done(function () {
                        //Doplneni casti, co se ma vykonat po dokonceni
                    })
                        .always(function () {
                        that.endOperation();
                        //that.endOperation();
                    });
                    return defClose.promise();
                }
                /**
                 * pozastavitPrikazy
                 *
                 * @param {JQuery} $grid
                 */
                pozastavitPrikazy($grid) {
                    let that = this;
                    that.vstupniDataDto.rows = $grid.ggrid("getSelection");
                    that.dialogs.confirm("Pozastavení", "Přejete si pozastavit vybrané příkazy k úhradě [" + that.vstupniDataDto.rows.length + "]?") //RC 24100119 : Na některých pohybech jsou ručně pořízené zápisy. Chcete zachovat zápisy těchto pohybů?
                        .on("yes", function () {
                        //filtry
                        that.vstupniDataDto.ikc = "0";
                        that.vstupniDataDto.rows = $grid.ggrid("getSelection");
                        that.element.findForms("formZadani").findFields().gfield("model", "collect", that.vstupniDataDto);
                        that.beginOperation("Probíhá pozastavení");
                        // deferred objekt pro zřetězení operací
                        let def = $.Deferred().resolve().promise();
                        // obsluha jednotlivých fází
                        def
                            .then(function () {
                            let def = $.Deferred();
                            that.isl.Prikaz.pozastav({ data: that.vstupniDataDto })
                                .get()
                                .then(function (ret) {
                                def.resolve();
                                return ret;
                            })
                                .fail(function (xhr, type, vobj) {
                                // operace nedopadla
                                def.reject(xhr, type, vobj);
                            });
                            return def.promise();
                        })
                            .then(function () {
                            // seznam prikazu
                            let def = $.Deferred();
                            // naplnění seznamu
                            that.fillSeznamDavek(that.$gridDavkyFazeKontrola, 1).then(function (data) {
                                that.endOperation();
                                def.resolve();
                            });
                            that.endOperation();
                            return def.promise();
                        })
                            .done(function () {
                            // ukončení
                            // TODO: je tady potřeba něco dalšího dělat? asi zaškrtnutí záznamů, která jsou bez chyby
                        })
                            .always(function () {
                            that.endOperation();
                        });
                    })
                        .on("close", function () {
                        return;
                    });
                }
